/**
 * Internal
 * */
type PersistableItem = {
  /**
   * @label User ID
   * @primaryField
   * @hidden
   */
  readonly id: string;
};

/**
 * User Profile
 * @label User Profile Form
 */
export type UserProfile = PersistableItem & {
  /**
   * @label Full Name
   */
  name: string;

  /**
   * @label Email Address
   * @format email
   */
  email?: string;

  /**
   * @label Age (Years)
   * @constraints.min 1
   * @constraints.max 120
   * @constraints.step 1
   */
  age: number;

  /**
   * @label Is Active?
   */
  isActive: boolean;

  /**
    * @label Role
    */
  role: "admin" | "user" | "guest";

  /**
   * @label Department
   * @allowCustomSelection
   */
  department: "Sales" | "Engineering" | "Marketing";
  
  /**
   * @label Tags
   * @constraints.defaultValue ["news","updates"]
   */
  tags: string[];

  /**
   * @label Profile Image
   * @customType FileUpload
   */
  profileImage?: string;

  /**
   * @label Attachments
   * @customType FileAttachment
   */
  attachments?: string[];

  /**
   * @label Department Record
   */
  departmentRecord?: Department;

  /**
   * @label Team
   */
  team?: Department[];

  /**
   * @hidden
   */
  internalNotes?: string;
}

/**
 * @label Department
 */
export type Department = PersistableItem & {
  /**
   * @label Name
   */
  name: string;
}
